import math
vals=[0,50,100,150]
def lanczos(x,a=3):
    if x==0: return 1.0
    if abs(x)>=a: return 0.0
    return a*math.sin(math.pi*x)*math.sin(math.pi*x/a)/(math.pi*math.pi*x*x)
def sample(pos, clamp=True, a=3):
    left=math.floor(pos-a+1); right=math.floor(pos+a)
    total=0; acc=0
    for i in range(left,right+1):
        ii=min(max(i,0),len(vals)-1) if clamp else i
        if ii<0 or ii>=len(vals): continue
        w=lanczos(pos-i,a)
        total+=w; acc+=vals[ii]*w
    return acc/total if total else 0
for offset in [-0.5,0,0.5,1.0]:
    print('offset',offset,[round(sample(y+offset)) for y in range(4)],[sample(y+offset) for y in range(4)])
