func main() {
    prog := filepath.Base(os.Args[0])

    fs := flag.NewFlagSet(prog, flag.ContinueOnError)
    fs.SetOutput(io.Discard)
    dMode := fs.Int("d", 0, "")
    scaleMode := fs.Int("s", 0, "")
    matteStr := fs.String("m", "000000", "")
    tc := fs.Int("tc", 0, "")
    tr := fs.Int("tr", 0, "")
    goMode := fs.Bool("go", false, "")
    noBG := fs.Bool("nobg", false, "")
    versionFlag := fs.Bool("version", false, "")
    creditsFlag := fs.Bool("credits", false, "")
    helpFlag := fs.Bool("help", false, "")
    // Go's flag package already treats -h and --help specially only if defined.
    hFlag := fs.Bool("h", false, "")

    if err := fs.Parse(os.Args[1:]); err != nil {
        fmt.Print(usageText(prog))
        os.Exit(2)
    }

    if *versionFlag {
        fmt.Println(version)
        return
    }
    if *creditsFlag {
        fmt.Print(creditsText())
        return
    }
    if *helpFlag || *hFlag {
        fmt.Print(usageText(prog))
        return
    }

    if fs.NArg() < 1 {
        fmt.Print(usageText(prog))
        os.Exit(2)
    }

    if *dMode < 0 || *dMode > 2 || *scaleMode < 0 || *scaleMode > 2 || *tc == 1 || *tr == 1 || *tc < 0 || *tr < 0 {
        fmt.Print(usageText(prog))
        os.Exit(2)
    }

    matte, ok := parseMatte(*matteStr)
    if !ok {
        fmt.Print(banner())
        errLogger.Printf("matte color : %s is not a hex-color", *matteStr)
        os.Exit(2)
    }

    cols, rows := terminalDefaults()
    if *tc > 0 {
        cols = *tc
    }
    if *tr > 0 {
        rows = *tr
    }
    if cols < 2 || rows < 2 {
        fmt.Print(usageText(prog))
        os.Exit(2)
    }

    img, err := loadImage(fs.Arg(0))
    if err != nil {
        fatalImageError(err)
    }

    src := imageToPixmap(img, matte)
    var pm Pixmap
    if *dMode == 0 {
        pm = scaleClassic(src, cols, rows, *scaleMode)
    } else {
        pm = scaleDither(src, cols, rows, *scaleMode)
    }
    if pm.W < 2 || pm.H < 2 {
        fatalImageError(errors.New("ANSImage: height or width must be >=2"))
    }

    var out string
    if *dMode == 0 {
        out = renderClassic(pm, *goMode)
    } else {
        out = renderDither(pm, *dMode, matte, *noBG, *goMode)
    }
    fmt.Print(out)
}

func fatalImageError(err error) {
    fmt.Print(banner())
    errLogger.Print(err)
    os.Exit(1)
}

func terminalDefaults() (int, int) {
    cols, rows := 80, 22
    if w, h, ok := getWinSize(os.Stdout.Fd()); ok && w >= 2 && h >= 4 {
        cols = w
        rows = h - 2
    }
    return cols, rows
}

type winsize struct {
    Row    uint16
    Col    uint16
    Xpixel uint16
    Ypixel uint16
}

func getWinSize(fd uintptr) (int, int, bool) {
    var ws winsize
    _, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
    if errno != 0 || ws.Col == 0 || ws.Row == 0 {
        return 0, 0, false
    }
    return int(ws.Col), int(ws.Row), true
}

func parseMatte(s string) (RGB, bool) {
    if s == "" {
        return RGB{}, true
    }
    isHex := func(b byte) bool {
        return ('0' <= b && b <= '9') || ('a' <= b && b <= 'f') || ('A' <= b && b <= 'F')
    }
    for i := 0; i < len(s); i++ {
        if !isHex(s[i]) {
            return RGB{}, false
        }
    }
    if len(s) == 3 {
        r, _ := strconv.ParseUint(strings.Repeat(string(s[0]), 2), 16, 8)
        g, _ := strconv.ParseUint(strings.Repeat(string(s[1]), 2), 16, 8)
        b, _ := strconv.ParseUint(strings.Repeat(string(s[2]), 2), 16, 8)
        return RGB{uint8(r), uint8(g), uint8(b)}, true
    }
    if len(s) == 1 || len(s) == 2 || len(s) == 4 {
        return RGB{}, false
    }
    // The observed parser accepts five or more hex digits, reads two, two,
    // and up to two digits, and ignores anything after the sixth digit.
    if len(s) >= 5 {
        r, err1 := strconv.ParseUint(s[0:2], 16, 8)
        g, err2 := strconv.ParseUint(s[2:4], 16, 8)
        end := 6
        if len(s) < end {
            end = len(s)
        }
        b, err3 := strconv.ParseUint(s[4:end], 16, 8)
        if err1 != nil || err2 != nil || err3 != nil {
            return RGB{}, false
        }
        return RGB{uint8(r), uint8(g), uint8(b)}, true
    }
    return RGB{}, false
}

func loadImage(name string) (image.Image, error) {
    var data []byte
    var err error
    if strings.HasPrefix(name, "http://") || strings.HasPrefix(name, "https://") {
        resp, err := http.Get(name)
        if err != nil {
            return nil, err
        }
        defer resp.Body.Close()
        data, err = io.ReadAll(resp.Body)
        if err != nil {
            return nil, err
        }
    } else {
        data, err = os.ReadFile(name)
        if err != nil {
            return nil, err
        }
    }
    img, _, err := image.Decode(bytes.NewReader(data))
    if err == nil {
        return img, nil
    }
    if bmp, berr := decodeBMP(data); berr == nil {
        return bmp, nil
    }
    return nil, err
}

func imageToPixmap(img image.Image, matte RGB) Pixmap {
    b := img.Bounds()
    w, h := b.Dx(), b.Dy()
    pm := Pixmap{W: w, H: h, Pix: make([]RGB, w*h)}
    for y := 0; y < h; y++ {
        for x := 0; x < w; x++ {
            r16, g16, b16, a16 := img.At(b.Min.X+x, b.Min.Y+y).RGBA()
            a := uint8(a16 >> 8)
            pr := uint8(r16 >> 8)
            pg := uint8(g16 >> 8)
            pb := uint8(b16 >> 8)
            pm.Set(x, y, RGB{
                blendPremul(pr, matte.R, a),
                blendPremul(pg, matte.G, a),
                blendPremul(pb, matte.B, a),
            })
        }
    }
    return pm
}

func blendPremul(premul, matte, alpha uint8) uint8 {
    add := (int(matte)*(255-int(alpha)) + 127) / 255
    v := int(premul) + add
    if v > 255 {
        v = 255
    }
    return uint8(v)
}

func scaleClassic(src Pixmap, cols, rows, mode int) Pixmap {
    switch mode {
    case 1:
        return resizeFill(src, cols, rows*2+2)
    case 2:
        return resizeFit(src, cols, rows*2)
    default:
        return resizePixmap(src, cols, rows*2+2)
    }
}

func scaleDither(src Pixmap, cols, rows, mode int) Pixmap {
    switch mode {
    case 1:
        return resizeFill(src, cols, rows)
    case 2:
        return resizeFit(src, cols, rows)
    default:
        return resizePixmap(src, cols, rows)
    }
}

func resizeFit(src Pixmap, maxW, maxH int) Pixmap {
    if src.W <= maxW && src.H <= maxH {
        return src
    }
    scale := math.Min(float64(maxW)/float64(src.W), float64(maxH)/float64(src.H))
    if scale > 1 {
        scale = 1
    }
    nw := int(math.Floor(float64(src.W)*scale + 1e-9))
    nh := int(math.Floor(float64(src.H)*scale + 1e-9))
    if nw < 1 {
        nw = 1
    }
    if nh < 1 {
        nh = 1
    }
    return resizePixmap(src, nw, nh)
}

func resizeFill(src Pixmap, targetW, targetH int) Pixmap {
    if targetW <= 0 || targetH <= 0 {
        return Pixmap{}
    }
    scale := math.Max(float64(targetW)/float64(src.W), float64(targetH)/float64(src.H))
    sw := int(math.Ceil(float64(src.W)*scale - 1e-9))
    sh := int(math.Ceil(float64(src.H)*scale - 1e-9))
    if sw < targetW {
        sw = targetW
    }
    if sh < targetH {
        sh = targetH
    }
    scaled := resizePixmap(src, sw, sh)
    ox := (scaled.W - targetW) / 2
    oy := (scaled.H - targetH) / 2
    out := Pixmap{W: targetW, H: targetH, Pix: make([]RGB, targetW*targetH)}
    for y := 0; y < targetH; y++ {
        copy(out.Pix[y*targetW:(y+1)*targetW], scaled.Pix[(y+oy)*scaled.W+ox:(y+oy)*scaled.W+ox+targetW])
    }
    return out
}

func resizePixmap(src Pixmap, nw, nh int) Pixmap {
    if nw <= 0 || nh <= 0 || src.W == 0 || src.H == 0 {
        return Pixmap{}
    }
    if src.W == nw && src.H == nh {
        return src
    }
    tmp := Pixmap{W: nw, H: src.H, Pix: make([]RGB, nw*src.H)}
    for y := 0; y < src.H; y++ {
        for x := 0; x < nw; x++ {
            pos := (float64(x)+0.5)*float64(src.W)/float64(nw) - 0.5
            tmp.Set(x, y, sampleHorizontal(src, y, pos))
        }
    }
    out := Pixmap{W: nw, H: nh, Pix: make([]RGB, nw*nh)}
    for y := 0; y < nh; y++ {
        pos := (float64(y)+0.5)*float64(src.H)/float64(nh) - 0.5
        for x := 0; x < nw; x++ {
            out.Set(x, y, sampleVertical(tmp, x, pos))
        }
    }
    return out
}

const cubicA = -0.75

func cubicWeight(x float64) float64 {
    if x < 0 {
        x = -x
    }
    if x < 1 {
        return (cubicA+2)*x*x*x - (cubicA+3)*x*x + 1
    }
    if x < 2 {
        return cubicA*x*x*x - 5*cubicA*x*x + 8*cubicA*x - 4*cubicA
    }
    return 0
}

func sampleHorizontal(src Pixmap, y int, pos float64) RGB {
    left := int(math.Floor(pos - 2 + 1))
    right := int(math.Floor(pos + 2))
    var wr, wg, wb, wt float64
    for i := left; i <= right; i++ {
        ii := i
        if ii < 0 {
            ii = 0
        } else if ii >= src.W {
            ii = src.W - 1
        }
        w := cubicWeight(pos - float64(i))
        c := src.At(ii, y)
        wr += float64(c.R) * w
        wg += float64(c.G) * w
        wb += float64(c.B) * w
        wt += w
    }
    return rgbFromFloats(wr/wt, wg/wt, wb/wt)
}

func sampleVertical(src Pixmap, x int, pos float64) RGB {
    top := int(math.Floor(pos - 2 + 1))
    bot := int(math.Floor(pos + 2))
    var wr, wg, wb, wt float64
    for i := top; i <= bot; i++ {
        ii := i
        if ii < 0 {
            ii = 0
        } else if ii >= src.H {
            ii = src.H - 1
        }
        w := cubicWeight(pos - float64(i))
        c := src.At(x, ii)
        wr += float64(c.R) * w
        wg += float64(c.G) * w
        wb += float64(c.B) * w
        wt += w
    }
    return rgbFromFloats(wr/wt, wg/wt, wb/wt)
}

func rgbFromFloats(r, g, b float64) RGB {
    return RGB{clampRound(r), clampRound(g), clampRound(b)}
}

func clampRound(v float64) uint8 {
    if math.IsNaN(v) || v < 0 {
        return 0
    }
    if v > 255 {
        return 255
    }
    return uint8(math.Floor(v + 0.5))
}

func renderClassic(pm Pixmap, goMode bool) string {
    var out strings.Builder
    for y := 2; y+1 < pm.H; y += 2 {
        var line strings.Builder
        for x := 0; x < pm.W; x++ {
            bg := pm.At(x, y)
            fg := pm.At(x, y+1)
            fmt.Fprintf(&line, "\x1b[48;2;%d;%d;%dm\x1b[38;2;%d;%d;%dm▄", bg.R, bg.G, bg.B, fg.R, fg.G, fg.B)
        }
        line.WriteString("\x1b[0m\n")
        writeOutputLine(&out, line.String(), goMode)
    }
    return out.String()
}

func renderDither(pm Pixmap, mode int, matte RGB, noBG bool, goMode bool) string {
    blockChars := []rune{' ', '░', '▒', '▓', '█'}
    asciiChars := []rune{' ', '.', ':', ';', '+', '=', 'x', 'X', '$', '&', '#'}
    var out strings.Builder
    for y := 0; y < pm.H; y++ {
        var line strings.Builder
        for x := 0; x < pm.W; x++ {
            c := pm.At(x, y)
            strength := int(c.R)
            if int(c.G) > strength {
                strength = int(c.G)
            }
            if int(c.B) > strength {
                strength = int(c.B)
            }
            var ch rune
            if mode == 1 {
                idx := (strength + 3) / 52
                if idx < 0 {
                    idx = 0
                }
                if idx >= len(blockChars) {
                    idx = len(blockChars) - 1
                }
                ch = blockChars[idx]
            } else {
                idx := 0
                if strength > 0 {
                    idx = (strength - 1) / 23
                }
                if idx >= len(asciiChars) {
                    idx = len(asciiChars) - 1
                }
                ch = asciiChars[idx]
            }
            if !noBG {
                fmt.Fprintf(&line, "\x1b[48;2;%d;%d;%dm", matte.R, matte.G, matte.B)
            }
            fmt.Fprintf(&line, "\x1b[38;2;%d;%d;%dm%c", c.R, c.G, c.B, ch)
        }
        line.WriteString("\x1b[0m\n")
        writeOutputLine(&out, line.String(), goMode)
    }
    return out.String()
}

func writeOutputLine(out *strings.Builder, line string, goMode bool) {
    if !goMode {
        out.WriteString(line)
        return
    }
    out.WriteString("fmt.Print(\"")
    out.WriteString(escapeGoPrint(line))
    out.WriteString("\")\n")
}

func escapeGoPrint(s string) string {
    var b strings.Builder
    for _, r := range s {
        switch r {
        case '\x1b':
            b.WriteString("\\033")
        case '\n':
            b.WriteString("\\n")
        case '\\':
            b.WriteString("\\\\")
        case '"':
            b.WriteString("\\\"")
        default:
            b.WriteRune(r)
        }
    }
    return b.String()
}

func decodeBMP(data []byte) (image.Image, error) {
    if len(data) < 54 || string(data[:2]) != "BM" {
        return nil, errors.New("not bmp")
    }
    off := int(binary.LittleEndian.Uint32(data[10:14]))
    dib := int(binary.LittleEndian.Uint32(data[14:18]))
    if dib < 40 || len(data) < 14+dib {
        return nil, errors.New("unsupported bmp")
    }
    width := int(int32(binary.LittleEndian.Uint32(data[18:22])))
    heightSigned := int(int32(binary.LittleEndian.Uint32(data[22:26])))
    if width <= 0 || heightSigned == 0 {
        return nil, errors.New("unsupported bmp")
    }
    topDown := heightSigned < 0
    height := heightSigned
    if height < 0 {
        height = -height
    }
    planes := binary.LittleEndian.Uint16(data[26:28])
    bpp := int(binary.LittleEndian.Uint16(data[28:30]))
    comp := binary.LittleEndian.Uint32(data[30:34])
    if planes != 1 || (comp != 0 && comp != 3) {
        return nil, errors.New("unsupported bmp")
    }
    img := image.NewNRGBA(image.Rect(0, 0, width, height))
    switch bpp {
    case 24:
        stride := ((width*3 + 3) / 4) * 4
        for y := 0; y < height; y++ {
            sy := y
            if !topDown {
                sy = height - 1 - y
            }
            row := off + sy*stride
            if row+width*3 > len(data) {
                return nil, errors.New("unsupported bmp")
            }
            for x := 0; x < width; x++ {
                i := row + x*3
                img.SetNRGBA(x, y, color.NRGBA{R: data[i+2], G: data[i+1], B: data[i], A: 255})
            }
        }
    case 32:
        stride := width * 4
        for y := 0; y < height; y++ {
            sy := y
            if !topDown {
                sy = height - 1 - y
            }
            row := off + sy*stride
            if row+width*4 > len(data) {
                return nil, errors.New("unsupported bmp")
            }
            for x := 0; x < width; x++ {
                i := row + x*4
                a := data[i+3]
                if a == 0 {
                    a = 255
                }
                img.SetNRGBA(x, y, color.NRGBA{R: data[i+2], G: data[i+1], B: data[i], A: a})
            }
        }
    case 8:
        colorsUsed := 0
        if len(data) >= 50 {
            colorsUsed = int(binary.LittleEndian.Uint32(data[46:50]))
        }
        if colorsUsed == 0 {
            colorsUsed = 256
        }
        palOff := 14 + dib
        if palOff+colorsUsed*4 > len(data) {
            return nil, errors.New("unsupported bmp")
        }
        pal := make([]color.NRGBA, colorsUsed)
        for i := 0; i < colorsUsed; i++ {
            j := palOff + i*4
            pal[i] = color.NRGBA{R: data[j+2], G: data[j+1], B: data[j], A: 255}
        }
        stride := ((width + 3) / 4) * 4
        for y := 0; y < height; y++ {
            sy := y
            if !topDown {
                sy = height - 1 - y
            }
            row := off + sy*stride
            if row+width > len(data) {
                return nil, errors.New("unsupported bmp")
            }
            for x := 0; x < width; x++ {
                idx := int(data[row+x])
                if idx >= len(pal) {
                    idx = 0
                }
                img.SetNRGBA(x, y, pal[idx])
            }
        }
    default:
        return nil, errors.New("unsupported bmp")
    }
    return img, nil
}
